const ctx = $('Resolve Event Type').first().json;
const res = $input.first().json || {};

if (!ctx.eventTypeId) {
  return vapiResult(ctx.toolCallId,
    'I could not reach the calendar just now. Offer to take their details and have Anthony call back with times.');
}
if (res.error || res.status === 'error') {
  return vapiResult(ctx.toolCallId,
    'I could not reach the calendar just now. Offer to take their details and have Anthony call back with times.');
}
const data = res.data || {};
const starts = [];
for (const day of Object.keys(data).sort()) {
  const arr = Array.isArray(data[day]) ? data[day] : [];
  for (const s of arr) { if (s && s.start) starts.push(s.start); }
}
if (starts.length === 0) {
  return vapiResult(ctx.toolCallId,
    'Nothing open in that window. Offer to take their details so Anthony can call with the next opening.');
}
// Spread the three offers across different days where possible — three slots on
// one morning is a worse offer than three across the week.
const byDay = {};
for (const s of starts) {
  const d = s.slice(0, 10);
  (byDay[d] = byDay[d] || []).push(s);
}
const days = Object.keys(byDay).sort();
const picks = [];
for (const d of days) { if (picks.length < 3) picks.push(byDay[d][0]); }
let i = 0;
while (picks.length < 3 && i < days.length) {
  const extra = byDay[days[i]][1];
  if (extra) picks.push(extra);
  i++;
}
picks.sort();
// book_job takes appointmentDate (YYYY-MM-DD) + appointmentTime (HH:MM, 24h, Eastern) —
// hand the model those exact values per slot so it never has to derive them itself.
function etParts(iso) {
  const d = new Date(iso);
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit',
    day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const p = Object.fromEntries(f.formatToParts(d).map(x => [x.type, x.value]));
  const hh = p.hour === '24' ? '00' : p.hour;
  return { date: p.year + '-' + p.month + '-' + p.day, time: hh + ':' + p.minute };
}
const lines = picks.map(iso => {
  const { date, time } = etParts(iso);
  return spokenSlot(iso) + ' [appointmentDate ' + date + ', appointmentTime ' + time + ']';
});
const text = 'Available: ' + lines.join('; or ') +
  '. Offer only these exact times, spoken naturally — never read the bracketed values aloud. ' +
  'When the caller picks one, pass its bracketed appointmentDate and appointmentTime to book_job exactly as written.';
return vapiResult(ctx.toolCallId, text);
